ON CONFLICT (issue_id) DO UPDATE SET status = EXCLUDED.status,
  severity = EXCLUDED.severity, resolved_at = EXCLUDED.resolved_at;

-- Sanity assertions; the whole seed rolls back if any of these fail ---
DO $$
DECLARE n INT;
BEGIN
  SELECT count(*) INTO n FROM administrative_units WHERE unit_type='CITY';
  IF n <> 1 THEN RAISE EXCEPTION 'expected 1 city, found %', n; END IF;
  SELECT count(*) INTO n FROM administrative_units WHERE unit_type='WARD';
  IF n <> 8 THEN RAISE EXCEPTION 'expected 8 wards, found %', n; END IF;
  SELECT count(*) INTO n FROM administrative_units WHERE unit_type='ROUTE_AREA';
  IF n <> 20 THEN RAISE EXCEPTION 'expected 20 route areas, found %', n; END IF;
  SELECT count(*) INTO n FROM properties WHERE route_id = 'ROUTE-DEMO-01';
  IF n <> 16 THEN RAISE EXCEPTION 'the 16 demo-lane properties were disturbed: %', n; END IF;
  SELECT count(*) INTO n FROM properties WHERE admin_unit_id IS NULL;
  IF n > 0 THEN RAISE EXCEPTION '% properties are not attached to the hierarchy', n; END IF;
  SELECT count(*) INTO n FROM property_surveys s
    LEFT JOIN properties p ON p.property_id = s.property_id WHERE p.property_id IS NULL;
  IF n > 0 THEN RAISE EXCEPTION '% orphaned survey rows', n; END IF;
  RAISE NOTICE 'City survey seed loaded: % admin units, % users, % assignments, % properties, % surveys, % QA issues.',
    (SELECT count(*) FROM administrative_units), (SELECT count(*) FROM survey_users),
    (SELECT count(*) FROM survey_assignments), (SELECT count(*) FROM properties),
    (SELECT count(*) FROM property_surveys), (SELECT count(*) FROM property_qa_issues);
END $$;

COMMIT;
